<script setup lang="ts">
import {ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {Command,ArrowRight,MessagesSquare,ShieldCheck,Workflow} from 'lucide-vue-next';import {useSession} from '../stores/session';import Notice from '../components/Notice.vue'
import type {Tenant} from '../types';const organizations=ref<Tenant[]>([]);const email=ref(''),password=ref(''),tenant=ref(''),busy=ref(false),error=ref(''),session=useSession(),router=useRouter(),route=useRoute()
async function login(){busy.value=true;error.value='';try{if(!organizations.value.length){organizations.value=await session.authenticate(email.value.trim(),password.value);if(!organizations.value.length)throw new Error('No tienes organizaciones asignadas.');if(organizations.value.length===1)tenant.value=String(organizations.value[0].tenant_id);else return}await session.chooseOrganization(Number(tenant.value));router.push('/')}catch(e){error.value=(e as Error).message}finally{password.value='';busy.value=false}}

function demo(){session.demo();router.push('/')}
</script>
<template><div class="login-page"><section class="login-story"><div class="brand"><span class="brand-symbol"><Command/></span>omniagent.</div><div><span class="eyebrow">CONECTA. CONVERSA. CRECE.</span><h1>Una mejor atención<br>empieza con una<br><em>buena conversación.</em></h1><p>Tu equipo, tus clientes y cada conversación.<br>Finalmente, en el mismo lugar.</p><div class="login-features"><span><MessagesSquare/>Atención omnicanal</span><span><Workflow/>Automatización inteligente</span><span><ShieldCheck/>Espacios por organización</span></div></div><small>Diseñado para equipos que conectan.</small></section><section class="login-form"><div class="login-card"><span class="eyebrow">BIENVENIDO A OMNIAGENT</span><h2>Tu espacio de trabajo te espera.</h2><p>Inicia sesión para continuar con tu equipo.</p><Notice v-if="route.query.expired">Tu sesión expiró. Vuelve a iniciar sesión.</Notice><Notice v-if="error" error>{{error}}</Notice><form @submit.prevent="login"><label v-if="!organizations.length">Correo electrónico<input v-model="email" type="email" autocomplete="username" maxlength="255" required placeholder="nombre@empresa.com"></label><label v-if="!organizations.length">Contraseña<input v-model="password" type="password" autocomplete="current-password" required placeholder="Tu contraseña"></label><label v-if="organizations.length>1">Organización<select v-model="tenant" aria-label="Organización" required><option value="" disabled>Selecciona tu organización</option><option v-for="org in organizations" :key="org.tenant_id" :value="org.tenant_id">{{org.organization}} · {{org.role}}</option></select></label><button class="button primary full" :disabled="busy">{{busy?'Verificando acceso…':'Iniciar sesión'}}<ArrowRight :size="17"/></button></form><div class="divider">O EXPLORA OMNIAGENT</div><button class="button full" :disabled="busy" @click="demo">Entrar al modo demostrativo <ArrowRight :size="17"/></button><p class="caption">Sin credenciales ni backend. Datos de ejemplo y cambios temporales.</p></div></section></div></template>
